export const DEPARTMENTS: string[] = ["Amazonas", "Antioquia", "Arauca", "Archipiélago de San Andrés, Providencia y Santa Catalina", "Atlántico", "Bogotá D.C.", "Bolívar", "Boyacá", "Caldas", "Caquetá", "Casanare", "Cauca", "Cesar", "Chocó", "Cundinamarca", "Córdoba", "Guainía", "Guaviare", "Huila", "La Guajira", "Magdalena", "Meta", "Nariño", "Norte de Santander", "Putumayo", "Quindío", "Risaralda", "Santander", "Sucre", "Tolima", "Valle del Cauca", "Vaupés", "Vichada"];

const BY_CODE = new Map(CITIES.map((c) => [c.c, c]));

export function cityByCode(code: string | null | undefined): City | null {
  if (!code) return null;
  return BY_CODE.get(code) ?? null;
}

export function cityLabel(code: string | null | undefined): string {
  const city = cityByCode(code);
  return city ? `${city.n}, ${city.d}` : '';
}

export function normalize(text: string): string {
  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

/** Busca municipios por nombre o departamento. Prioriza los que empiezan por el término. */
export function searchCities(query: string, limit = 8): City[] {
  const q = normalize(query);
  if (!q) return [];
  const starts: City[] = [];
  const contains: City[] = [];
  for (const city of CITIES) {
    if (city.s.startsWith(q)) starts.push(city);
    else if (city.s.includes(q)) contains.push(city);
    if (starts.length >= limit) break;
  }
  return [...starts, ...contains].slice(0, limit);
}
